rch.float16, \"FP16 input required\")\n41:     require(bool(torch.isfinite(x).all().item()), \"all values must be finite\")\n42:     return {\"valid\": True, \"shape\": list(x.shape)}\n43: \n44: \n45: def run(x):\n46:     validate_inputs(x)\n47:     m, n = x.shape\n48:     with torch.cuda.device(x.device):\n49:         output = torch.empty((m,), dtype=torch.int64, device=x.device)\n50:         _argmax_kernel[(m,)](x, output, N=n, BLOCK=triton.next_power_of_2(n), num_warps=4)\n51:     return output\n52: \n53: \n54: def reference(x):\n55:     \"\"\"FP16-to-FP64 conversion is exact; numerical ties use the first index.\"\"\"\n56:     validate_inputs(x, require_cuda=False)\n57:     return torch.argmax(x.to(torch.float64), dim=1)\n58: \n59: \n60: def make_inputs(device=\"cuda\", rows=17, columns=257, seed=0):\n61:     \"\"\"Convenience examples, not a restriction on the input domain.\"\"\"\n62:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n63:     x = torch.randn((rows, columns), generator=generator).to(torch.float16)\n64:     return (x.to(device),)",
